UPDATE accounts t SET owner_user_id = t.added_by WHERE t.owner_user_id IS NULL;
INSERT INTO ownership_backfill (table_name, tenant_id, rule, derived_rows, fallback_rows)
   SELECT 'accounts', t.tenant_id, 'column:added_by', count(*) FILTER (WHERE t.owner_user_id IS NOT NULL), count(*) FILTER (WHERE t.owner_user_id IS NULL) FROM accounts t GROUP BY t.tenant_id;
UPDATE accounts t SET owner_user_id = pg_temp.first_user(t.tenant_id) WHERE t.owner_user_id IS NULL;
ALTER TABLE accounts ENABLE TRIGGER USER;
ALTER TABLE accounts ALTER COLUMN owner_user_id SET DEFAULT app_user(), ALTER COLUMN owner_user_id SET NOT NULL;
CREATE INDEX ix_accounts_tenant_owner ON accounts (tenant_id, owner_user_id);
CREATE TRIGGER fill_owner BEFORE INSERT ON accounts FOR EACH ROW
   WHEN (NEW.added_by IS NOT NULL) EXECUTE FUNCTION fill_owner('column', 'added_by');
