CREATE POLICY tenant_owner_isolation ON accounts TO app_rw
   USING (tenant_id = (SELECT app_tenant()) AND (owner_user_id = (SELECT app_user()) OR (SELECT app_scope()) = 'system'))
   WITH CHECK (tenant_id = (SELECT app_tenant()) AND (owner_user_id = (SELECT app_user()) OR (SELECT app_scope()) = 'system'));

